entries[286921] = { ["name"] = "Gezeitenalchemistenstein", ["text"] = "Wirken in 3 sek.\nReagenzien:\nAkundas Biss (50), Winterkuss (50), Ankerkraut (15), Expulsom (15), Gezeitenkern (15)\nStellt einen Gezeitenalchemistenstein her.\nBeruf:\nAlchemie von Battle for Azeroth (130)\nLehrer:\nKumali die Kluge\nZone:\nZuldazar\nKosten:\n30\n\nGezeitenalchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+ 9 Vielseitigkeit\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 25 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n50\nBenötigt Alchemie von Kul Tiras\n(130)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
entries[286922] = { ["name"] = "Lebendiger Alchemistenstein", ["text"] = "Wirken in 3 sek.\nReagenzien:\nAkundas Biss (60), Winterkuss (60), Ankerkraut (20), Expulsom (20), Atem von Bwonsamdi (20)\nStellt einen lebendigen Alchemistenstein her.\nBeruf:\nAlchemie von Battle for Azeroth (130)\nEntdeckung:\nGezeitenalchemistenstein\n\nLebendiger Alchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+ 10 Vielseitigkeit\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 26 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n50\nBenötigt Alchemie von Kul Tiras\n(100)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
